package com.bank.jsonfn.model;
import java.math.BigDecimal;
import java.util.*;

public class Customer {
    private final String id, name; private final BigDecimal balance;
    private String status; private final List<String> nominees;
    public Customer(String id, String name, BigDecimal balance, String status, List<String> nominees) {
        this.id = id; this.name = name; this.balance = balance; this.status = status;
        this.nominees = new ArrayList<>(nominees);
    }
    public String getId() { return id; }
    public String getName() { return name; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
    public void setStatus(String s) { this.status = s; }
    public List<String> getNominees() { return nominees; }
}
