package com.bank.jsonfn.service;
import com.bank.jsonfn.model.Customer;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class CustomerSummaryService {
    private static final Logger log = Logger.getLogger(CustomerSummaryService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final Map<String, Customer> store = new LinkedHashMap<>();
    public CustomerSummaryService(List<Customer> list) { list.forEach(c -> store.put(c.getId(), c)); }

    // jsonb_build_object: mix normalized columns + a JSON field into one summary
    public Map<String,Object> buildSummary(String id) {
        Customer c = store.get(id);
        Map<String,Object> s = new LinkedHashMap<>();
        s.put("id", c.getId()); s.put("name", c.getName());
        s.put("balance", c.getBalance()); s.put("status", c.getStatus());
        log.info(() -> "buildSummary " + id + " -> " + s);
        return s;
    }
    // jsonb_set on path {status}
    public void setStatus(String id, String status) {
        store.get(id).setStatus(status);
        log.info(() -> "jsonb_set status=" + status + " for " + id);
    }
    // jsonb_array_elements on nominees
    public List<String> nominees(String id) { return store.get(id).getNominees(); }
}
