package com.bank.jsonfn;
import com.bank.jsonfn.model.Customer;
import com.bank.jsonfn.service.CustomerSummaryService;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class JsonFnDemo {
    public static void main(String[] args) {
        CustomerSummaryService svc = new CustomerSummaryService(List.of(
            new Customer("SAV2001","Rajesh Kumar", new BigDecimal("1000000.00"),"pending", List.of("Sita","Mohan")),
            new Customer("CUR3001","Priya Sharma", new BigDecimal("250000.00"),"active", List.of("Arjun"))));
        System.out.println(svc.buildSummary("SAV2001"));
        svc.setStatus("SAV2001","active");
        System.out.println("Rajesh nominees -> " + svc.nominees("SAV2001"));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
